@RestController
@RequestMapping("/api/orders")
public class OrderController {
    @Autowired
    private OrderService orderService;

    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody OrderRequest request) {
        var order = orderService.create(request);
        var location = URI.create("/api/orders/" + order.id());
        return ResponseEntity.created(location).body(order);  // 201 with Location header
    }

    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        return orderService.findById(id)
            .map(ResponseEntity::ok)              // 200 if found
            .orElse(ResponseEntity.notFound().build());  // 404 if not found
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteOrder(@PathVariable Long id) {
        orderService.delete(id);
        return ResponseEntity.noContent().build();  // 204 No Content
    }
}

@RestController
@RequestMapping("/api/users")
public class UserController {
    @Autowired
    private UserService userService;

    @PostMapping  // 201 Created
    public ResponseEntity<User> createUser(@Valid @RequestBody UserRequest request) {
        var user = userService.create(request);
        var location = URI.create("/api/users/" + user.id());
        return ResponseEntity.created(location).body(user);
    }

    @GetMapping("/{id}")  // 200 OK or 404 Not Found
    public ResponseEntity<User> getUser(@PathVariable Long id) {
        return userService.findById(id)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
    }

    @PutMapping("/{id}")  // 200 OK or 404 Not Found
    public ResponseEntity<User> updateUser(@PathVariable Long id, @Valid @RequestBody UserRequest request) {
        return userService.update(id, request)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
    }

    @DeleteMapping("/{id}")  // 204 No Content
    public ResponseEntity<Void> deleteUser(@PathVariable Long id) {
        userService.delete(id);
        return ResponseEntity.noContent().build();
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {
    @Autowired
    private ProductService productService;

    @PostMapping
    public ResponseEntity<Product> createProduct(@RequestBody ProductRequest request) {
        var product = productService.create(request);

        var headers = new HttpHeaders();
        headers.setLocation(URI.create("/api/products/" + product.id()));  // Location header
        headers.setCacheControl(CacheControl.noCache());  // Cache-Control: no-cache
        headers.add("X-Request-ID", UUID.randomUUID().toString());  // Custom trace header

        return ResponseEntity.status(HttpStatus.CREATED)
            .headers(headers)
            .body(product);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Product> getProduct(@PathVariable Long id) {
        return productService.findById(id)
            .map(product -> {
                var cacheControl = CacheControl.maxAge(1, TimeUnit.HOURS);  // Cache for 1 hour
                return ResponseEntity.ok()
                    .cacheControl(cacheControl)
                    .eTag(String.valueOf(product.version()))  // ETag for conditional requests
                    .body(product);
            })
            .orElse(ResponseEntity.notFound().build());
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    @Autowired
    private OrderService orderService;

    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        return orderService.findById(id)  // returns Optional<Order>
            .map(ResponseEntity::ok)       // 200 OK if present
            .orElse(ResponseEntity.notFound().build());  // 404 if empty
    }

    @GetMapping("/search")
    public ResponseEntity<?> searchOrders(@RequestParam String query) {
        if (query.isBlank()) {
            return ResponseEntity.badRequest()
                .body(new ErrorResponse("Query parameter required"));  // 400 with error
        }
        var orders = orderService.search(query);
        return ResponseEntity.ok(orders);  // 200 with list
    }

    @PostMapping("/{id}/ship")
    public ResponseEntity<ShipmentResult> shipOrder(@PathVariable Long id) {
        return orderService.ship(id)
            .map(result -> ResponseEntity.ok(result))  // 200 on success
            .orElseGet(() -> ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new ShipmentResult(false, "Order already shipped")));  // 409 on conflict
    }
}

@RestController
@RequestMapping("/api/users")
public class UserController {
    @Autowired
    private UserRepository userRepository;

    @GetMapping
    public Page<User> getAllUsers(Pageable pageable) {  // Pageable from query params
        return userRepository.findAll(pageable);  // Returns Page<User> with metadata
    }

    @GetMapping("/search")
    public List<User> searchUsers(@RequestParam String name) {
        return userRepository.findByNameContaining(name);  // Small result set, List is OK
    }

    @GetMapping("/{id}")
    public ResponseEntity<User> getUserById(@PathVariable Long id) {
        return userRepository.findById(id)  // Returns Optional<User>
            .map(ResponseEntity::ok)         // 200 if found
            .orElse(ResponseEntity.notFound().build());  // 404 if not found
    }

    @GetMapping("/{id}/summary")
    public UserSummary getUserSummary(@PathVariable Long id) {  // Always exists or throws
        var user = userRepository.findById(id)
            .orElseThrow(() -> new ResourceNotFoundException("User not found"));
        return new UserSummary(user.name(), user.email());  // Transform to DTO
    }
}
